xlength="3" placeholder="USD" required></label></div><div class="form-row"><label>Taux<input type="number" name="rate" step="0.00000001" min="0.00000001" required></label><label>Date<input type="date" name="effective_date" value="<?= e(date('Y-m-d')) ?>" required></label></div><button class="button secondary">Enregistrer le taux</button></form><?php foreach($rates as $rate): ?><div class="settings-row"><span><?= e($rate['from_currency']) ?> → <?= e($rate['to_currency']) ?> · <?= e($rate['rate']) ?> · <?= e($rate['effective_date']) ?></span></div><?php endforeach; ?></section></div>
<section class="analytics-panel category-spend-panel"><p class="eyebrow">DEPENSES PAR CATEGORIE</p><h2>12 derniers mois</h2><?php if(!$byCategory): ?><p class="subheading">Aucune depense sur cette periode.</p><?php else: foreach($byCategory as $row): ?><div class="metric-row"><span><?= e($row['category']) ?> · <?= e($row['currency']) ?></span><b><?= e(number_format((float)$row['total'],2,',',' ')) ?></b></div><?php endforeach; endif; ?></section><section class="section-head section-spaced"><div><p class="eyebrow">HISTORIQUE RÉCENT</p><h2>Achats et dépenses</h2></div></section><?php if(!$purchases): ?><div class="empty-state"><p>Aucune dépense enregistrée.</p></div><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Achat</th><th>Vêtement lié</th><th>Montant</th><th></th></tr></thead><tbody><?php foreach($purchases as $purchase): ?><tr><td><?= e($purchase['purchased_at']) ?></td><td><?= e($purchase['item_name']) ?></td><td><?= e($purchase['clothing_name']??'—') ?></td><td><?= e(number_format((float)$purchase['amount'],2,',',' ')) ?> <?= e($purchase['currency']) ?></td><td><form method="post" action="<?= e(url('purchase-delete')) ?>" data-confirm="Supprimer cette dépense ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($purchase['id']) ?>"><button class="text-button">Supprimer</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
